atoms.reference_cedar:
permit (principal is User, action == Action::"requestCatalogue", resource is CourseCatalogue)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.semesterIsBeginning
};

permit (principal is User, action == Action::"registerCourse", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
};

permit (principal is User, action == Action::"addCourseSelection", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.isCurrentSelection
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
    && resource.offering.addDropOpen
};

permit (principal is User, action == Action::"updateCourseSelection", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.isCurrentSelection
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
    && resource.offering.addDropOpen
};

permit (principal is User, action == Action::"deleteCourseSelection", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.isCurrentSelection
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
    && resource.offering.addDropOpen
};

permit (principal is User, action == Action::"viewReportCard", resource is ReportCard)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.previousSemesterCompleted
};

permit (principal is User, action == Action::"selectTeachingOffering", resource is CourseOffering)
when {
    principal.role == "professor"
    && resource.isUpcomingSemester
    && resource.registrationOpen
    && !resource.hasTeachingConflict
    && resource.eligibleProfessors.contains(principal)
};

permit (principal is User, action == Action::"modifyAssignedOffering", resource is CourseOffering)
when {
    principal.role == "professor"
    && resource.registrationOpen
    && resource has instructor
    && resource.instructor == principal
};

permit (principal is User, action == Action::"viewRoster", resource is CourseOffering)
when {
    principal.role == "professor"
    && resource has instructor
    && resource.instructor == principal
};

permit (principal is User, action == Action::"enterGrade", resource is GradeRecord)
when {
    principal.role == "professor"
    && resource.previousSemesterCompleted
    && resource.professor == principal
    && resource.offering has instructor
    && resource.offering.instructor == principal
};

permit (principal is User, action == Action::"changeStudentInfo", resource is StudentInfo)
when {
    principal.role == "registrar"
};

permit (principal is User, action == Action::"closeRegistration", resource is RegistrationProcess)
when {
    principal.role == "registrar"
    && resource.isCurrentSemester
    && resource.isOpen
};

permit (principal is User, action == Action::"registerCourse", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
};

permit (principal is User, action == Action::"addCourseSelection", resource is CourseSelection)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.isCurrentSelection
    && resource.offering.isCurrentSemester
    && resource.offering.registrationOpen
    && resource.offering.addDropOpen
};

permit (principal is User, action == Action::"viewReportCard", resource is ReportCard)
when {
    principal.role == "student"
    && context.onCampusLan
    && resource.student == principal
    && resource.previousSemesterCompleted
};

permit (principal is User, action == Action::"selectTeachingOffering", resource is CourseOffering)
when {
    principal.role == "professor"
    && resource.isUpcomingSemester
    && resource.registrationOpen
    && !resource.hasTeachingConflict
    && resource.eligibleProfessors.contains(principal)
};

permit (principal is User, action == Action::"enterGrade", resource is GradeRecord)
when {
    principal.role == "professor"
    && resource.previousSemesterCompleted
    && resource.professor == principal
    && resource.offering has instructor
    && resource.offering.instructor == principal
};

permit (principal is User, action == Action::"closeRegistration", resource is RegistrationProcess)
when {
    principal.role == "registrar"
    && resource.isCurrentSemester
    && resource.isOpen
};
